#!/usr/bin/env python3
# Copyright 2026 Stephan Schlöpke
# SPDX-License-Identifier: Apache-2.0
"""Generate the shared terminal width table of both CLIs from Python's Unicode data.

Width 0: nonspacing/enclosing marks, format and control characters (except
U+00AD) and Hangul medial/final jamo. Width 2: East Asian Wide/Fullwidth,
unassigned code points of planes 2 and 3, and the regional indicators, the only
Emoji_Presentation scalars without a wide East Asian Width. Everything else is 1.

--check verifies that both generated files hold the same table and, when this
Python's Unicode version matches the recorded one, that they are current.
"""

from __future__ import annotations

import argparse
import re
import sys
import unicodedata
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
CSHARP = ROOT / "implementation/csharp/GameEventScript.Tool/src/ToolTextWidths.cs"
SWIFT = ROOT / "implementation/swift/GameEventScriptTool/Sources/GameEventScriptTool/ToolTextWidths.swift"
HEADER = "// Copyright 2026 Stephan Schlöpke\n// SPDX-License-Identifier: Apache-2.0\n"
NOTICE = "// Generated by scripts/generate-terminal-widths.py from Unicode {version}; do not edit.\n"


def width(scalar: int) -> int:
    if 0x1160 <= scalar <= 0x11FF or 0xD7B0 <= scalar <= 0xD7FF:
        return 0
    if 0x1F1E6 <= scalar <= 0x1F1FF:
        return 2
    character = chr(scalar)
    category = unicodedata.category(character)
    if category == "Cn" and (0x20000 <= scalar <= 0x2FFFD or 0x30000 <= scalar <= 0x3FFFD):
        return 2
    if category in ("Mn", "Me", "Cc") or category == "Cf" and scalar != 0xAD:
        return 0
    return 2 if unicodedata.east_asian_width(character) in ("W", "F") else 1


def runs() -> list[tuple[int, int]]:
    result: list[tuple[int, int]] = []
    for scalar in range(0x110000):
        if 0xD800 <= scalar <= 0xDFFF:
            continue
        value = width(scalar)
        if not result or result[-1][1] != value:
            result.append((scalar, value))
    return result


def rows(values: list[str], indent: str) -> str:
    return "\n".join(indent + " ".join(values[index:index + 16]) for index in range(0, len(values), 16))


def csharp(version: str, table: list[tuple[int, int]]) -> str:
    starts = rows([f"0x{start:X}," for start, _ in table], "        ")
    widths = rows([f"{value}," for _, value in table], "        ")
    return f"""{HEADER}{NOTICE.format(version=version)}
namespace GameEventScript.Tool;

internal static class ToolTextWidths
{{
    internal const string UnicodeVersion = "{version}";

    // Each run starts at its scalar and lasts until the next start.
    internal static ReadOnlySpan<int> Starts =>
    [
{starts}
    ];

    internal static ReadOnlySpan<byte> Widths =>
    [
{widths}
    ];
}}
"""


def swift(version: str, table: list[tuple[int, int]]) -> str:
    starts = rows([f"0x{start:X}," for start, _ in table], "        ")
    widths = rows([f"{value}," for _, value in table], "        ")
    return f"""{HEADER}{NOTICE.format(version=version)}
enum ToolTextWidths {{
    static let unicodeVersion = "{version}"

    // Each run starts at its scalar and lasts until the next start.
    static let starts: [UInt32] = [
{starts}
    ]

    static let widths: [UInt8] = [
{widths}
    ]
}}
"""


def parse(text: str) -> tuple[str, list[str], list[str]]:
    version = re.search(r'nicode ?[Vv]ersion = "([^"]+)"', text)
    blocks = re.findall(r"\[\n(.*?)\n    \]", text, re.S)
    if version is None or len(blocks) != 2:
        raise ValueError("unrecognized generated width table")
    return version.group(1), blocks[0].split(), blocks[1].split()


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--check", action="store_true", help="verify the generated files instead of writing them")
    arguments = parser.parse_args()
    version = unicodedata.unidata_version
    if not arguments.check:
        table = runs()
        CSHARP.write_text(csharp(version, table), encoding="utf-8")
        SWIFT.write_text(swift(version, table), encoding="utf-8")
        print(f"Generated {len(table)} width runs from Unicode {version}.")
        return 0
    try:
        recorded = parse(CSHARP.read_text(encoding="utf-8"))
        if parse(SWIFT.read_text(encoding="utf-8")) != recorded:
            print("error: the C# and Swift terminal width tables differ.", file=sys.stderr)
            return 1
    except (OSError, ValueError) as error:
        print(f"error: {error}", file=sys.stderr)
        return 1
    if recorded[0] != version:
        print(f"Both width tables match (Unicode {recorded[0]}); Python provides Unicode {version}, so currency is not checked.")
        return 0
    table = runs()
    if CSHARP.read_text(encoding="utf-8") != csharp(version, table) or SWIFT.read_text(encoding="utf-8") != swift(version, table):
        print("error: the terminal width tables are stale; run scripts/generate-terminal-widths.py.", file=sys.stderr)
        return 1
    print(f"Both width tables are current for Unicode {version}.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
